1	package security
2	
3	import (
4		tea "github.com/charmbracelet/bubbletea"
5	
6		"github.com/anthnel/devdesk/internal/command"
7		"github.com/anthnel/devdesk/internal/jobs"
8	)
9	
10	// What is being rescanned is the registry's answer, not this view's (§3.58).
11	//
12	// `scanTarget.Scanning` was a flag this view set and cleared itself, and
13	// `handleInventoryLoaded` had to carry it across every reload by hand: the
14	// caches say nothing about a scan that has not finished writing to them, so a
15	// refresh landing mid-rescan cleared the spinner and left the row looking
16	// settled. Reading the snapshot removes the reconciliation rather than fixing
17	// it — there is nothing to carry across a reload when the state was never here.
18	//
19	// It also makes the marker true for a scan started **elsewhere**. The inventory
20	// lists what `ws` and the images tab scan; a rescan launched from either of them
21	// is the same work on the same cache entry, and this view had no way to know.
22	
23	// handleJobsChanged takes the router's snapshot and redecorates the rows.
24	func (m Model) handleJobsChanged(msg jobs.ChangedMsg) (tea.Model, tea.Cmd) {
25		m.jobs = msg.Runs
26		m.setInventory(m.inventory.Items())
27		return m, nil
28	}
29	
30	// handleFrameMsg takes the animation's frame and redecorates the rows.
31	func (m Model) handleFrameMsg(msg jobs.FrameMsg) (tea.Model, tea.Cmd) {
32		m.jobFrame = msg.Frame
33		m.setInventory(m.inventory.Items())
34		return m, nil
35	}
36	
37	// scanRun builds the run behind ctrl+s and A. The label names the screen it was
38	// launched from, which is what `:jobs` shows.
39	func (m Model) scanRun(names []string) jobs.Run {
40		return jobs.NewRun(jobs.KindScan, command.ViewSecurity, "", "inventory", names...)
41	}
42	
43	// scanningTarget reports whether a target is queued or being scanned, whoever
44	// started it.
45	func (m Model) scanningTarget(name string) bool {
46		return m.scanningTargets()[name]
47	}
48	
49	// scanningTargets is every target with a scan in flight, from any view.
50	func (m Model) scanningTargets() map[string]bool {
51		out := make(map[string]bool)
52		for _, run := range jobs.Unfinished(m.jobs) {
53			if run.Kind != jobs.KindScan {
54				continue
55			}
56			for _, item := range run.Items {
57				if !item.State.Terminal() {
58					out[item.Target] = true
59				}
60			}
61		}
62		return out
63	}
64	
65	// ── What each message tells the registry (jobs.Reporter) ─────────────────────
66	
67	func (m InventoryScanStartingMsg) Transition() jobs.Transition {
68		return jobs.Transition{Kind: jobs.KindScan, Target: m.Name, State: jobs.ItemRunning, Cancel: m.Cancel}
69	}
70	
71	func (m InventoryScanFinishedMsg) Transition() jobs.Transition {
72		t := jobs.Transition{Kind: jobs.KindScan, Target: m.Name, State: jobs.ItemDone}
73		if m.Err != nil {
74			t.State = jobs.ItemFailed
75			t.Detail = "scan failed — check logs"
76		}
77		return t
78	}
79	
80	// D10: rescanCmd had no starting message at all — only a finished one — so its
81	// items would have jumped straight from queued to done and the distinction
82	// between the two would have been decorative here.
83	var (
84		_ jobs.Reporter = InventoryScanStartingMsg{}
85		_ jobs.Reporter = InventoryScanFinishedMsg{}
86	)
