package jobs

import (
	"path/filepath"
	"slices"
	"time"
)

// MaxFailures caps how many remembered failures the registry keeps.
const MaxFailures = 500

// FailureKey identifies what failed: an operation kind on one target in one
// context. Target is always a TargetKey.
type FailureKey struct {
	Kind    Kind
	Target  string
	Context string
}

// Failure is the last remembered failure for a FailureKey. The registry
// stores it with an already normalized key.
type Failure struct {
	FailureKey
	// Display is the human-readable name of the target.
	Display string
	// Detail is the failure reason.
	Detail string
	At     time.Time
}

// TargetKey normalizes a target so every view naming the same thing produces
// the same key. Only absolute paths are cleaned; image references, forge
// paths and slugs are kept verbatim, since two spellings of an image
// ("nginx", "nginx:latest") are not provably the same target.
func TargetKey(target string) string {
	if filepath.IsAbs(target) {
		return filepath.Clean(target)
	}
	return target
}

// FailureFor returns the failure remembered for kind on target in
// contextName. The target is normalized with TargetKey.
func FailureFor(failures []Failure, kind Kind, target, contextName string) (Failure, bool) {
	key := FailureKey{Kind: kind, Target: TargetKey(target), Context: contextName}
	for _, f := range failures {
		if f.FailureKey == key {
			return f, true
		}
	}
	return Failure{}, false
}

// FailuresOn returns a copy of the failures on target in contextName, in the
// order of the input slice. With no kinds, every kind is kept. An empty
// target is not special: it matches only failures stored with an empty target.
func FailuresOn(failures []Failure, contextName, target string, kinds ...Kind) []Failure {
	target = TargetKey(target)
	var out []Failure
	for _, f := range failures {
		if f.Context != contextName || f.Target != target {
			continue
		}
		if len(kinds) > 0 && !slices.Contains(kinds, f.Kind) {
			continue
		}
		out = append(out, f)
	}
	return out
}
package jobs

import "slices"

// Active is one item of a run that is running or queued on a target.
type Active struct {
	Kind  Kind
	RunID JobID
	Item  Item
}

// ActiveOn returns the running and queued items on target in contextName:
// running ones first, then queued ones, each group in run order. The target is
// normalized with TargetKey on both sides. With no kinds, every kind is kept.
// Items are copied by value, without their cancel hook. No match returns nil.
func ActiveOn(runs []Run, contextName, target string, kinds ...Kind) []Active {
	target = TargetKey(target)
	var running, queued []Active
	for _, r := range runs {
		if r.Context != contextName || (len(kinds) > 0 && !slices.Contains(kinds, r.Kind)) {
			continue
		}
		for _, it := range r.Items {
			if TargetKey(it.Target) != target {
				continue
			}
			it.cancel = nil
			a := Active{Kind: r.Kind, RunID: r.ID, Item: it}
			switch it.State {
			case ItemRunning:
				running = append(running, a)
			case ItemQueued:
				queued = append(queued, a)
			}
		}
	}
	return append(running, queued...)
}
	if r.clock == nil {
		return time.Now()
	}
	return r.clock()
}

// Failures returns a copy of the remembered failures, oldest first. Like the
// rest of the registry it is read from Update alone (Rule 110).
func (r *Registry) Failures() []Failure {
	return slices.Clone(r.failures)
}

// Forget drops every failure of every kind on target in contextName, and those
// below it when target is an absolute path. It reports whether anything went.
func (r *Registry) Forget(target, contextName string) bool {
	target = TargetKey(target)
	before := len(r.failures)
	r.failures = slices.DeleteFunc(r.failures, func(f Failure) bool {
		return f.Context == contextName && (f.Target == target || isBelow(f.Target, target))
	})
	return len(r.failures) != before
}

// record is the single rule of the failure memory, called after an item's
// state is written: failed poses, done clears (and a successful delete forgets
// the target for every kind). Any other state, including skipped, changes
// nothing. The context is the run's, so a failure landing after a context
// switch is filed under the context it ran in.
func (r *Registry) record(run *Run, item Item) {
	switch item.State {
	case ItemFailed:
		if run.Kind.Remembered() {
			r.pose(Failure{
				FailureKey: failureKey(run.Kind, item.Target, run.Context),
				Display:    item.Name(),
				Detail:     item.Detail,
				At:         r.now(),
			})
		}
	case ItemDone:
		r.clear(failureKey(run.Kind, item.Target, run.Context))
		if run.Kind == KindDelete {
			r.Forget(item.Target, run.Context)
		}
	}
}

// pose stores f as the last failure for its key. Re-posing a key moves it to
// the newest position; past MaxFailures the oldest entry is evicted.
func (r *Registry) pose(f Failure) {
	r.clear(f.FailureKey)
	r.failures = append(r.failures, f)
	if excess := len(r.failures) - MaxFailures; excess > 0 {
		r.failures = slices.Delete(r.failures, 0, excess)
	}
}

// clear drops the failure stored under key, if any.
func (r *Registry) clear(key FailureKey) {
	r.failures = slices.DeleteFunc(r.failures, func(f Failure) bool { return f.FailureKey == key })
}

func failureKey(kind Kind, target, contextName string) FailureKey {
	return FailureKey{Kind: kind, Target: TargetKey(target), Context: contextName}
}

// isBelow reports whether path is strictly inside dir. Only absolute paths
// have descendants: image references and forge paths are matched exactly.
func isBelow(path, dir string) bool {
	if !filepath.IsAbs(path) || !filepath.IsAbs(dir) {
		return false
	}
	rel, err := filepath.Rel(dir, path)
	return err == nil && rel != "." && rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator))
}
func CancelItem(id JobID, target string) tea.Cmd {
	return func() tea.Msg { return CancelItemMsg{ID: id, Target: target} }
}

// ForgetTargetMsg says a target no longer exists, for a removal the registry did
// not run (an image remove). The router stamps the current context.
type ForgetTargetMsg struct{ Target string }

// ForgetTarget builds the message.
func ForgetTarget(target string) tea.Cmd {
	return func() tea.Msg { return ForgetTargetMsg{Target: target} }
}

// StartInContext builds the message for work that writes into a context-scoped
// cache. The builder is called once, in Update, with the name the router
// stamped on the run — so every command it returns carries that name however
// long the batch runs.
func StartInContext(run Run, work func(contextName string) tea.Cmd) tea.Cmd {
	return func() tea.Msg { return StartMsg{Run: run, Work: work} }
}

// ChangedMsg carries what the registry holds to every view that might show it.
// It is the whole of the broadcast (D1): a view keeps its own copy of a
// snapshot rather than reading a pointer the router writes, so nothing is read
// from View() while something else is writing it.
//
// It is sent when the registry changes: a run started, a transition, a seal.
// The animation (the spinner frame, the blink phase) is not part of it: it
// travels in FrameMsg, to the view on screen only, so a tick never makes every
// held view rebuild its rows (DEVDESK-139).
//
// It lives in this package rather than in the router's so that every view can
// name it without importing the router, which imports them.
type ChangedMsg struct {
	// Runs is a copy, oldest first, every context included. Filtering on the
	// current one is the view's business (D8, FilterContext).
	Runs []Run

	// Failures is a copy of what the registry remembers about failed targets,
	// oldest first, every context included. Like Runs, it is read by the view
	// and never written back.

