96	func TestActivityGuardPendingListOnlyShrinks(t *testing.T) {
97		if got := len(pendingTables); got > maxPendingTables {
98			t.Errorf("pendingTables has %d entries, ceiling is %d: the list may only shrink (A-16 criterion 6)", got, maxPendingTables)
99		}
100		seen := map[string]bool{}
101		for _, p := range pendingTables {
102			if p.Story == "" {
103				t.Errorf("pending table %q names no story", p.Table)
104			}
105			if seen[p.Table] {
106				t.Errorf("pending table %q is listed twice", p.Table)
107			}
108			seen[p.Table] = true
109		}
110	}
111	
112	// builtView returns the view the router builds for vt, laid out at 60x30.
113	func builtView(t *testing.T, vt command.ViewType) tea.Model {
114		t.Helper()
115		a := routerAt(t, &bareView{}, 60, 30) // isolateHome, session-only secrets
116		a.createView(vt)
117		m := a.views[vt]
118		if m == nil {
119			t.Fatalf("view %q: the router did not build it", vt)
120		}
121		m, _ = m.Update(tea.WindowSizeMsg{Width: 60, Height: 30})
122		return m
123	}
124	
125	// classificationProblems says what is wrong with the classification of one
126	// view, empty when it is fine. It works per table: a view may be migrated for
127	// some tables and pending for others (A-09a/A-09b, A-10a/A-10b) as long as the
128	// two sets are disjoint; an exempt view is neither migrated nor pending.
129	func classificationProblems(vt command.ViewType, migrated map[command.ViewType][]string, pending []pendingTable, exempt map[command.ViewType]string) []string {
130		var problems []string
131		mig := migrated[vt]
132		var pend []string
133		for _, p := range pending {
134			if p.View == vt {
135				pend = append(pend, p.Table)
136			}
137		}
138		_, isExempt := exempt[vt]
139		switch {
140		case len(mig) == 0 && len(pend) == 0 && !isExempt:
141			problems = append(problems, "neither migrated, pending (with its story) nor exempt (with its reason)")
142		case isExempt && (len(mig) > 0 || len(pend) > 0):
143			problems = append(problems, "exempt and also migrated or pending")
144		}
145		for _, name := range pend {
146			if contains(mig, name) {
147				problems = append(problems, fmt.Sprintf("table %q is both migrated and pending", name))
148			}
149		}
150		return problems
151	}
152	
153	// staleExceptions lists the pending tables of a view that the view already
154	// reports: their exception must go.
155	func staleExceptions(vt command.ViewType, reported []string, pending []pendingTable) []string {
156		var stale []string
157		for _, p := range pending {
158			if p.View == vt && contains(reported, p.Table) {
159				stale = append(stale, p.Table)
160			}
161		}
162		return stale
163	}
164	
165	// Criterion 6: every view the router builds is migrated, pending or exempt.
166	func TestActivityGuardEveryViewIsClassified(t *testing.T) {
167		for _, name := range command.AllViewNames() {
168			vt := command.ViewType(name)
169			t.Run(name, func(t *testing.T) {
170				for _, p := range classificationProblems(vt, migratedTables, pendingTables, exemptViews) {
171					t.Errorf("view %q is %s: classify it in activity_guard_test.go", vt, p)
172				}
173			})
174		}
175	}
176	
177	// The logic itself, on a fictitious view that is partly migrated.
178	func TestActivityGuardClassificationLogic(t *testing.T) {
179		const v command.ViewType = "fiction"
180		pending := []pendingTable{{"fiction/b", v, "A-99"}}
181		tests := []struct {
182			name     string
183			migrated map[command.ViewType][]string
184			pending  []pendingTable
185			exempt   map[command.ViewType]string
186			problems int
187			stale    []string
188			reported []string
189		}{
190			{"partly migrated is fine", map[command.ViewType][]string{v: {"fiction/a"}}, pending, nil, 0, nil, []string{"fiction/a"}},
191			{"unclassified fails", nil, nil, nil, 1, nil, nil},
192			{"same table both ways fails", map[command.ViewType][]string{v: {"fiction/b"}}, pending, nil, 1, []string{"fiction/b"}, []string{"fiction/b"}},
193			{"exempt and pending fails", nil, pending, map[command.ViewType]string{v: "why"}, 1, nil, nil},
194			{"pending table not reported is not stale", map[command.ViewType][]string{v: {"fiction/a"}}, pending, nil, 0, nil, []string{"fiction/a"}},
195		}
196		for _, tt := range tests {
197			t.Run(tt.name, func(t *testing.T) {
198				if got := classificationProblems(v, tt.migrated, tt.pending, tt.exempt); len(got) != tt.problems {
199					t.Errorf("problems = %v, want %d", got, tt.problems)
200				}
201				if got := staleExceptions(v, tt.reported, tt.pending); !equalStrings(got, tt.stale) {
202					t.Errorf("stale = %v, want %v", got, tt.stale)
203				}
204			})
205		}
206	}
207	
208	func equalStrings(a, b []string) bool {
209		if len(a) != len(b) {
210			return false
211		}
212		for i := range a {
213			if a[i] != b[i] {
214				return false
215			}
216		}
217		return true
218	}
219	
220	// Criteria 1, 4 and the help half of 5, at runtime, on the views the router builds.
221	func TestActivityGuardMigratedViews(t *testing.T) {
222		legendTitle := indicator.Legend().Title
223		for vt, want := range migratedTables {
224			t.Run(string(vt), func(t *testing.T) {
225				m := builtView(t, vt)
226				av, ok := m.(activityView)
227				if !ok {
228					t.Fatalf("view %q is migrated but does not expose ActivityTables()", vt)
229				}
230				tables := av.ActivityTables()
231				for _, name := range want {
232					tb, ok := tables[name]
233					if !ok {
234						t.Errorf("view %q: table %q is migrated but ActivityTables() does not report it (reported: %v)", vt, name, sortedKeys(tables))
235						continue
236					}
237					checkColumnZero(t, vt, name, tb.Shapes())
238					// Criterion 4, Rule 116: the rendered extent, never the sum of columns.
239					if got, want := tb.RenderedWidth(), 60-2; got != want {
240						t.Errorf("view %q table %q: RenderedWidth() = %d at 60 columns, want %d (Rule 116)", vt, name, got, want)
241					}
242				}
243				for name := range tables {
244					if !contains(want, name) {
245						t.Errorf("view %q reports table %q, which migratedTables does not list", vt, name)
246					}
247				}
248				// Criterion 5, help half: the legend.
249				hp, ok := m.(help.Provider)
250				if !ok {
251					t.Fatalf("view %q has no help", vt)
252				}
253				found := false
254				for _, s := range hp.GetHelpContent().Sections {
255					found = found || s.Title == legendTitle
256				}
257				if !found {
258					t.Errorf("view %q: help has no %q section (indicator.Legend)", vt, legendTitle)
259				}
260			})
261		}
262	}
263	
264	// Criterion 6, other direction: a view that reports a table still listed as
265	// pending has migrated it; the exception must go. An exempt view must report
266	// none at all.
267	func TestActivityGuardNoStaleException(t *testing.T) {
268		for _, name := range command.AllViewNames() {
269			vt := command.ViewType(name)
270			_, isExempt := exemptViews[vt]
271			if !isExempt && len(pendingViews()[vt]) == 0 {
272				continue
273			}
274			t.Run(name, func(t *testing.T) {
275				av, ok := builtView(t, vt).(activityView)
276				if !ok {
277					return
278				}
279				if isExempt {
280					t.Errorf("view %q exposes ActivityTables() but is exempt: move it out of exemptViews", vt)
281				}
282				reported := sortedKeys(av.ActivityTables())
283				if stale := staleExceptions(vt, reported, pendingTables); len(stale) > 0 {
284					t.Errorf("view %q reports %v, still listed as pending: remove the exception", vt, stale)
285				}
286			})
287		}
288	}
289	
290	func checkColumnZero(t *testing.T, vt command.ViewType, table string, shapes []datatable.ColumnShape) {
291		t.Helper()
292		if len(shapes) == 0 {
293			t.Errorf("view %q table %q: no column reported", vt, table)
294			return
295		}
296		c := shapes[0]
297		var bad []string
298		if !c.Indicator {
299			bad = append(bad, "not an Indicator column")
300		}
301		if c.Title != "" {
302			bad = append(bad, fmt.Sprintf("title %q (want empty)", c.Title))
303		}
304		if c.Sizing != datatable.SizingFixed {
305			bad = append(bad, "not SizingFixed")
306		}
307		if c.MinWidth != datatable.IconColumnWidth {
308			bad = append(bad, fmt.Sprintf("MinWidth %d (want IconColumnWidth)", c.MinWidth))
309		}
310		if c.Less || c.Search {
311			bad = append(bad, "declares Less or Search")
312		}
313		if len(bad) > 0 {
314			t.Errorf("view %q table %q: column 0 is wrong: %s (A-16 criterion 1)", vt, table, strings.Join(bad, "; "))
315		}
316	}
317	
318	// migratedSources are the source prefixes (a directory ending in "/" or a file
319	// path, relative to internal/) of each migrated view. They are scanned for the
320	// retired mechanisms (criterion 2a/2b, and the hard-coded glyphs of 3). Only
321	// migrated views: pending ones still use them. A prefix may be a file so a view
322	// that migrates in two steps (OCI A-09a/b, explorer A-10a/b) can be scanned
323	// file by file.
324	var migratedSources = map[command.ViewType][]string{
325		command.ViewJobs:       {"ui/jobsview/"},
326		command.ViewWorkspaces: {"ui/workspaces/"},
327	}
328	
329	// sourceDeclarationProblems says what is wrong with the link between migrated
330	// views and the sources scanned for them, empty when it is fine. files are the
331	// paths relative to internal/ of every non-test source file.
332	func sourceDeclarationProblems(migrated map[command.ViewType][]string, sources map[command.ViewType][]string, files []string) []string {
333		var problems []string
334		for vt := range migrated {
335			if len(sources[vt]) == 0 {
336				problems = append(problems, fmt.Sprintf("view %q is migrated but declares no source to scan in migratedSources", vt))
337			}
338		}
339		for vt, prefixes := range sources {
340			if len(migrated[vt]) == 0 {
341				problems = append(problems, fmt.Sprintf("view %q has sources in migratedSources but is not migrated (migratedTables)", vt))
342			}
343			for _, p := range prefixes {
344				if !anyHasPrefix(files, p) {
345					problems = append(problems, fmt.Sprintf("view %q: source prefix %q matches no file", vt, p))
346				}
347			}
348		}
349		sort.Strings(problems)
350		return problems
351	}
352	
353	func anyHasPrefix(files []string, prefix string) bool {
354		for _, f := range files {
355			if prefix != "" && strings.HasPrefix(f, prefix) {
356				return true
357			}
358		}
359		return false

