422	// finding is one retired mechanism found in a source file.
423	type finding struct {
424		Pos  token.Position // file:line:column
425		What string
426	}
427	
428	// bubbleTeaName returns the local name file gives the bubbletea import: its
429	// alias, "." for a dot import, "tea" when unnamed, or "" when the file does not
430	// import it (or blank-imports it). A different package that happens to be
431	// called tea is therefore not mistaken for it.
432	func bubbleTeaName(file *ast.File) string {
433		for _, imp := range file.Imports {
434			path, err := strconv.Unquote(imp.Path.Value)
435			if err != nil || path != "github.com/charmbracelet/bubbletea" {
436				continue
437			}
438			switch {
439			case imp.Name == nil:
440				return "tea"
441			case imp.Name.Name == "_":
442				return ""
443			default:
444				return imp.Name.Name
445			}
446		}
447		return ""
448	}
449	
450	// retiredMechanisms reports, in a migrated view's file, every retired
451	// mechanism: AdvanceSpinner, a StatusColumn: key, a frame field, an activity
452	// glyph literal, and any reference to bubbletea's Tick / Every (under whatever name the file
453	// imports it) outside declaredViewTicks.
454	// rel is the file's path relative to internal/; it is the key of a declared tick.
455	// RenderedFrame (a method of the viewport frame) is allowed.
456	func retiredMechanisms(fset *token.FileSet, file *ast.File, rel string) []finding {
457		var out []finding
458		report := func(pos token.Pos, what string) {
459			out = append(out, finding{Pos: fset.Position(pos), What: what})
460		}
461		tea := bubbleTeaName(file)
462		selectors := map[*ast.Ident]bool{} // identifiers seen as the Sel of a selector
463		// reportTick flags any reference to bubbletea's Tick / Every, called or not
464		// (`var tick = tea.Tick` is as much a tick as `tea.Tick(...)`), unless the
465		// enclosing "<file>:<function>" is declared.
466		reportTick := func(pos token.Pos, fn, name string) {
467			if name != "Tick" && name != "Every" {
468				return
469			}
470			if _, declared := declaredViewTicks[rel+":"+fn]; !declared {
471				report(pos, "reference to bubbletea's "+name+" (a view's rows are animated by the router's tick)")
472			}
473		}
474		isFrame := func(name string) bool {
475			return name == "Frame" || name == "frame" || name == "SpinnerFrame"
476		}
477		visit := func(fn string) func(ast.Node) bool {
478			return func(n ast.Node) bool {
479				switch x := n.(type) {
480				case *ast.CallExpr:
481					sel, ok := x.Fun.(*ast.SelectorExpr)
482					if !ok {
483						break
484					}
485					if sel.Sel.Name == "AdvanceSpinner" {
486						report(x.Pos(), "call to AdvanceSpinner")
487					}
488				case *ast.KeyValueExpr:
489					if id, ok := x.Key.(*ast.Ident); ok {
490						if id.Name == "StatusColumn" {
491							report(id.Pos(), "StatusColumn: key")
492						}
493						if isFrame(id.Name) {
494							report(id.Pos(), "frame field "+id.Name+": set")
495						}
496					}
497				case *ast.Field:
498					for _, id := range x.Names {
499						if isFrame(id.Name) {
500							report(id.Pos(), "frame field "+id.Name)
501						}
502					}
503				case *ast.Ident:
504					// Dot import: a bare Tick / Every that no declaration in the file binds.
505					if tea == "." && x.Obj == nil && !selectors[x] {
506						reportTick(x.Pos(), fn, x.Name)
507					}
508				case *ast.SelectorExpr:
509					selectors[x.Sel] = true
510					if pkg, ok := x.X.(*ast.Ident); ok && tea != "" && tea != "." && pkg.Name == tea {
511						reportTick(x.Pos(), fn, x.Sel.Name)
512					}
513					if isFrame(x.Sel.Name) {
514						report(x.Sel.Pos(), "frame selector ."+x.Sel.Name)
515					}
516				case *ast.BasicLit:
517					if x.Kind == token.STRING || x.Kind == token.CHAR {
518						s, err := strconv.Unquote(x.Value)
519						if x.Kind == token.CHAR {
520							var q rune
521							q, _, _, err = strconv.UnquoteChar(x.Value[1:len(x.Value)-1], '\'')
522							s = string(q)
523						}
524						if err == nil && strings.ContainsAny(s, activityGlyphs) {
525							report(x.Pos(), "activity glyph written as a literal "+x.Value+" (use indicator.Glyph)")
526						}
527					}
528				}
529				return true
530			}
531		}
532		for _, decl := range file.Decls {
533			fn := ""
534			if fd, ok := decl.(*ast.FuncDecl); ok {
535				fn = fd.Name.Name
536			}
537			if gd, ok := decl.(*ast.GenDecl); ok && gd.Tok == token.CONST {
538				for _, spec := range gd.Specs {
539					if isDeclaredGlyphConstant(rel, spec) {
540						continue
541					}
542					ast.Inspect(spec, visit(fn))
543				}
544				continue
545			}
546			ast.Inspect(decl, visit(fn))
547		}
548		return out
549	}
