551	// isDeclaredGlyphConstant reports whether spec defines only constants declared in
552	// declaredGlyphConstants for the file rel.
553	func isDeclaredGlyphConstant(rel string, spec ast.Spec) bool {
554		vs, ok := spec.(*ast.ValueSpec)
555		if !ok || len(vs.Names) == 0 {
556			return false
557		}
558		for _, id := range vs.Names {
559			if _, declared := declaredGlyphConstants[rel+":"+id.Name]; !declared {
560				return false
561			}
562		}
563		return true
564	}
