1	package app
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9	
10		"github.com/charmbracelet/x/ansi"
11	
12		"github.com/anthnel/devdesk/internal/command"
13		"github.com/anthnel/devdesk/internal/jobs"
14		"github.com/anthnel/devdesk/internal/ui/indicator"
15		"github.com/anthnel/devdesk/internal/ui/testutil"
16		"github.com/anthnel/devdesk/internal/ui/workspaces"
17	)
18	
19	// DEVDESK-144 step 5: what only the router can show about the ws activity
20	// column. The failure lives in jobs.Registry, so it outlives the view.
21	
22	// wsRouter hosts the real ws view on a workspaces directory holding one git
23	// repository, "api". It returns the router and the repository's path.
24	func wsRouter(t *testing.T) (*App, string) {
25		t.Helper()
26		testutil.FastTimers(t, &animationFastInterval)
27		a := routerAt(t, &bareView{}, 180, 40)
28		dir := t.TempDir()
29		repo := filepath.Join(dir, "api")
30		if err := os.MkdirAll(filepath.Join(repo, ".git"), 0o755); err != nil {
31			t.Fatal(err)
32		}
33		a.config.App.WorkspacesDir = dir
34		return a, repo
35	}
36	
37	// openWorkspaces switches to ws and feeds the router what the view's Init
38	// loaded (listing and scan cache), as the runtime would.
39	func openWorkspaces(t *testing.T, a *App) {
40		t.Helper()
41		switchCmd := a.switchView(command.ViewWorkspaces)
42		_ = switchCmd // its batch carries tick timers; the listing is read below
43		for _, msg := range testutil.Msgs(a.views[command.ViewWorkspaces].Init()) {
44			a.Update(msg)
45		}
46		a.resize(a.width, a.height)
47	}
48	
49	// wsScreen is the ws view's body, ANSI stripped.
50	func wsScreen(a *App) string { return ansi.Strip(a.views[command.ViewWorkspaces].View()) }
51	
52	// rowOf returns the screen line naming name.
53	func rowOf(t *testing.T, screen, name string) string {
54		t.Helper()
55		for _, line := range strings.Split(screen, "\n") {
56			if strings.Contains(line, name) {
57				return line
58			}
59		}
60		t.Fatalf("no row names %q:\n%s", name, screen)
61		return ""
62	}
63	
64	func failScanOnRow(t *testing.T, a *App, repo string) {
65		t.Helper()
66		a.Update(jobs.StartMsg{Run: jobs.NewRun(jobs.KindScan, command.ViewWorkspaces, "", "ws", repo)})
67		a.Update(workspaces.WorkspaceScanCompleteMsg{RepoPath: repo, Error: errors.New("boom")})
68	}
69	
70	func failedGlyph() string { return indicator.Glyph(indicator.Failed, true) }
71	
72	// A-07 criterion 6: the red mark survives ctrl+r.
73	func TestWsFailureSurvivesRefresh(t *testing.T) {
74		a, repo := wsRouter(t)
75		openWorkspaces(t, a)
76		failScanOnRow(t, a, repo)
77		if !strings.Contains(rowOf(t, wsScreen(a), "api"), failedGlyph()) {
78			t.Fatalf("the failed scan left no %s on the row:\n%s", failedGlyph(), wsScreen(a))
79		}
80	
81		_, cmd := a.Update(testutil.Key("ctrl+r"))
82		for _, msg := range testutil.Msgs(cmd) {
83			a.Update(msg)
84		}
85		if !strings.Contains(rowOf(t, wsScreen(a), "api"), failedGlyph()) {
86			t.Errorf("ctrl+r cleared the %s:\n%s", failedGlyph(), wsScreen(a))
87		}
88	}
89	
90	// Leaving ws for :jobs and coming back keeps it, and so does a rebuilt view.
91	func TestWsFailureSurvivesLeavingAndARebuiltView(t *testing.T) {
92		a, repo := wsRouter(t)
93		openWorkspaces(t, a)
94		failScanOnRow(t, a, repo)
95	
96		a.switchView(command.ViewJobs)
97		openWorkspaces(t, a)
98		if !strings.Contains(rowOf(t, wsScreen(a), "api"), failedGlyph()) {
99			t.Errorf("coming back from :jobs lost the %s", failedGlyph())
100		}
101	
102		// A config save or a context switch rebuilds every view.
103		delete(a.views, command.ViewWorkspaces)
104		openWorkspaces(t, a)
105		if !strings.Contains(rowOf(t, wsScreen(a), "api"), failedGlyph()) {
106			t.Errorf("a rebuilt view lost the %s; the registry snapshot was not re-delivered on enter:\n%s", failedGlyph(), wsScreen(a))
107		}
108	}
109	
110	// The memory is per context: hidden in B, back in A.
111	func TestWsFailureIsFilteredByContext(t *testing.T) {
112		a, repo := wsRouter(t)
113		openWorkspaces(t, a)
114		failScanOnRow(t, a, repo)
115	
116		a.currentContext = "other"
117		delete(a.views, command.ViewWorkspaces)
118		openWorkspaces(t, a)
119		if strings.Contains(rowOf(t, wsScreen(a), "api"), failedGlyph()) {
120			t.Errorf("context other shows the failure of context default")
121		}
122	
123		a.currentContext = "default"
124		delete(a.views, command.ViewWorkspaces)
125		openWorkspaces(t, a)
126		if !strings.Contains(rowOf(t, wsScreen(a), "api"), failedGlyph()) {
127			t.Errorf("back in context default the failure is gone")
128		}
129	}
130	
131	// A-07 criterion 7, the :sec contract: (KindScan, TargetKey(abs path), context).
132	func TestWsScanFailureKeyIsTheOneSecReads(t *testing.T) {
133		a, repo := wsRouter(t)
134		openWorkspaces(t, a)
135	
136		// entry.Path is absolute (H3): the listing joins the expanded directory.
137		var loaded *workspaces.EntriesLoadedMsg
138		for _, msg := range testutil.Msgs(a.views[command.ViewWorkspaces].Init()) {
139			if l, ok := msg.(workspaces.EntriesLoadedMsg); ok {
140				loaded = &l
141			}
142		}
143		if loaded == nil || len(loaded.Entries) != 1 {
144			t.Fatalf("the listing returned %+v, want the one repository", loaded)
145		}
146		if got := loaded.Entries[0].Path; !filepath.IsAbs(got) || got != repo {
147			t.Fatalf("entry.Path = %q, want the absolute %q", got, repo)
148		}
149	
150		failScanOnRow(t, a, loaded.Entries[0].Path)
151		f, ok := jobs.FailureFor(a.jobs.Failures(), jobs.KindScan, jobs.TargetKey(repo), "default")
152		if !ok {
153			t.Fatalf("no scan failure under (KindScan, %q, default): %+v", jobs.TargetKey(repo), a.jobs.Failures())
154		}
155		if f.Target != filepath.Clean(repo) || !filepath.IsAbs(f.Target) {
156			t.Errorf("Target = %q, want the cleaned absolute path", f.Target)
157		}
158		if got := jobs.FailuresOn(a.jobs.Failures(), "default", repo, jobs.KindScan); len(got) != 1 {
